#!/usr/bin/env node
// kar-citelock — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-citelock repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// MIT licence.
// ---- KERNEL (from index.html) ----
/* ---------- constants ---------- */
var ALGO_VERSION = 'citelock-v2';
var NEAR_THRESHOLD = 0.90;
var ZERO_HASH = '0'.repeat(64);

/* ---------- text normalization ---------- */
function normalize(s){
  if (typeof s !== 'string') return '';
  var out = s;
  try { out = out.normalize('NFKC'); } catch(e){ /* older engines: skip */ }
  out = out
    .replace(/[‘’‛′]/g, "'")
    .replace(/[“”‟″]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/ /g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return out;
}

/* ---------- hashing ---------- */
function hasSubtle(){
  return !!(globalThis.crypto && globalThis.crypto.subtle && globalThis.crypto.subtle.digest);
}
async function sha256Hex(str){
  if (!hasSubtle()) throw new Error('Web Crypto (crypto.subtle) is not available in this context.');
  var enc = new TextEncoder().encode(str);
  var buf = await globalThis.crypto.subtle.digest('SHA-256', enc);
  var bytes = new Uint8Array(buf);
  var hex = '';
  for (var i=0;i<bytes.length;i++){ hex += bytes[i].toString(16).padStart(2,'0'); }
  return hex;
}

/* ---------- canonical JSON ---------- */
function canonicalize(obj){
  if (Array.isArray(obj)) return obj.map(canonicalize);
  if (obj && typeof obj === 'object'){
    var out = {};
    Object.keys(obj).sort().forEach(function(k){ out[k] = canonicalize(obj[k]); });
    return out;
  }
  return obj;
}
function canonicalJSON(obj){ return JSON.stringify(canonicalize(obj)); }

/* ---------- matching algorithm ---------- */
function levenshtein(a, b){
  var al = a.length, bl = b.length;
  if (al === 0) return bl;
  if (bl === 0) return al;
  var prev = new Array(bl+1);
  for (var j=0;j<=bl;j++) prev[j] = j;
  for (var i=1;i<=al;i++){
    var cur = new Array(bl+1);
    cur[0] = i;
    var ca = a.charCodeAt(i-1);
    for (var j2=1;j2<=bl;j2++){
      var cost = (ca === b.charCodeAt(j2-1)) ? 0 : 1;
      var del = prev[j2] + 1;
      var ins = cur[j2-1] + 1;
      var sub = prev[j2-1] + cost;
      cur[j2] = Math.min(del, ins, sub);
    }
    prev = cur;
  }
  return prev[bl];
}
function similarity(a, b){
  var maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  return 1 - (levenshtein(a,b) / maxLen);
}

function findAnchor(quote, sourceNorm){
  var words = quote.split(' ').filter(function(w){ return w.length > 0; });
  var maxLen = Math.min(words.length, 8);
  for (var len = maxLen; len >= 3; len--){
    for (var start = 0; start + len <= words.length; start++){
      var phrase = words.slice(start, start+len).join(' ');
      var idx = sourceNorm.indexOf(phrase);
      if (idx !== -1){
        var quoteOffset = quote.indexOf(phrase);
        if (quoteOffset === -1) quoteOffset = 0;
        return { sourceIdx: idx, quoteOffset: quoteOffset, phrase: phrase };
      }
    }
  }
  return null;
}

function contextSnippet(norm, idx, len, pad){
  pad = pad || 30;
  var start = Math.max(0, idx - pad);
  var end = Math.min(norm.length, idx + len + pad);
  var s = norm.slice(start, end);
  if (start > 0) s = '…' + s;
  if (end < norm.length) s = s + '…';
  return s;
}

// A letter or digit of a script written with spaces between words. Scripts written without them (Han, Hiragana,
// Katakana, Thai, Lao, Khmer, Myanmar) have no word edges, so a quote in them may match anywhere, as in v1.
var NO_SPACE_SCRIPTS = /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Thai}\p{Script=Lao}\p{Script=Khmer}\p{Script=Myanmar}]/u;
function isWordChar(c){
  return typeof c === 'string' && /^[\p{L}\p{N}]$/u.test(c) && !NO_SPACE_SCRIPTS.test(c);
}

// The first place the quote appears as whole words: it must not start or end in the middle of a word. v1 took any
// substring, so "he said yes" was VERIFIED in "she said yes" and "lice" in "police".
function findWhole(hay, needle){
  var from = 0, i;
  while ((i = hay.indexOf(needle, from)) !== -1){
    var startsClean = !isWordChar(needle.charAt(0)) || !isWordChar(hay.charAt(i - 1));
    var endsClean = !isWordChar(needle.charAt(needle.length - 1)) || !isWordChar(hay.charAt(i + needle.length));
    if (startsClean && endsClean) return i;
    from = i + 1;
  }
  return -1;
}

function verifyClaim(quoteRaw, src){
  var quote = normalize(quoteRaw);
  if (!quote) return { verdict:'EMPTY', similarity:0, excerpt:'' };
  if (!src || typeof src.norm !== 'string') return { verdict:'SOURCE_MISSING', similarity:0, excerpt:'' };

  var idx = findWhole(src.norm, quote);
  if (idx !== -1){
    return { verdict:'VERIFIED', similarity:1, excerpt: contextSnippet(src.norm, idx, quote.length) };
  }

  var anchor = findAnchor(quote, src.norm);
  if (!anchor){
    return { verdict:'NOT_FOUND', similarity:0, excerpt:'' };
  }

  var baseIdx = anchor.sourceIdx - anchor.quoteOffset;
  var best = null;
  for (var off = -20; off <= 20; off += 4){
    var start = Math.max(0, Math.min(src.norm.length, baseIdx + off));
    var end = Math.max(0, Math.min(src.norm.length, start + quote.length));
    var windowText = src.norm.slice(start, end);
    if (!windowText) continue;
    var sim = similarity(quote, windowText);
    if (!best || sim > best.sim) best = { sim: sim, idx: start };
  }
  if (!best) return { verdict:'NOT_FOUND', similarity:0, excerpt:'' };

  // The quote's exact text is there, but only inside longer words ("he said yes" in "she said yes"): measure it
  // against the whole words it sits in, so the score and the excerpt show what the source really says.
  var len = quote.length;
  if (best.sim === 1){
    var s = best.idx, e = best.idx + quote.length;
    // charAt past either end is '', never a word character, so each loop stops at the edge of the source
    while (isWordChar(src.norm.charAt(s - 1)) && isWordChar(src.norm.charAt(s))) s--;
    while (isWordChar(src.norm.charAt(e)) && isWordChar(src.norm.charAt(e - 1))) e++;
    best = { sim: similarity(quote, src.norm.slice(s, e)), idx: s };
    len = e - s;
  }

  var verdict = best.sim >= NEAR_THRESHOLD ? 'NEAR_MATCH' : 'NOT_FOUND';
  return {
    verdict: verdict,
    similarity: best.sim,
    excerpt: contextSnippet(src.norm, best.idx, len)
  };
}

/* ---------- sources, runs, receipts, ledger (shared by the page and the skill script) ---------- */
async function makeSource(label, text){
  var norm = normalize(text);
  return { label: label, norm: norm, hash: await sha256Hex(norm), length: norm.length };
}

function verifyAll(sources, claims){
  return claims.map(function(c){
    var src = sources.find(function(s){ return s.label === c.sourceLabel; });
    if (!src) return { verdict:'SOURCE_MISSING', similarity:0, excerpt:'' };
    return verifyClaim(c.quoteRaw, src);
  });
}

function summarizeVerdicts(results){
  var counts = {};
  results.forEach(function(r){ counts[r.verdict] = (counts[r.verdict]||0)+1; });
  return Object.keys(counts).sort().map(function(k){ return k + ':' + counts[k]; }).join('|');
}

function receiptPayload(sources, claims, results){
  var sortedSources = sources.slice().sort(function(a,b){ return a.label < b.label ? -1 : a.label > b.label ? 1 : 0; });
  var claimRows = claims.map(function(c, i){
    var r = results[i];
    return {
      source: c.sourceLabel,
      quote: normalize(c.quoteRaw),
      locator: c.locator || '',
      verdict: r.verdict,
      similarity: (typeof r.similarity === 'number' ? r.similarity : 0).toFixed(4)
    };
  }).sort(function(a,b){
    var ka = a.source + '\u0000' + a.quote + '\u0000' + a.locator;
    var kb = b.source + '\u0000' + b.quote + '\u0000' + b.locator;
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
  return {
    algorithm: ALGO_VERSION,
    nearThreshold: NEAR_THRESHOLD.toFixed(2),
    sources: sortedSources.map(function(s){ return { label: s.label, sha256: s.hash, length: s.length }; }),
    claims: claimRows
  };
}

function chainHash(prevChainHash, receiptHash, summary){
  return sha256Hex(prevChainHash + ':' + receiptHash + ':' + summary);
}

async function verifyLedger(entries){
  var list = Array.isArray(entries) ? entries : [];
  var checks = [];
  var expectedPrev = ZERO_HASH;
  for (var i=0;i<list.length;i++){
    var e = list[i] || {};
    var prevMatches = (e.prevChainHash === expectedPrev);
    var chainMatches = ((await chainHash(e.prevChainHash, e.receiptHash, e.summary)) === e.chainHash);
    checks.push({ n: e.n, ok: prevMatches && chainMatches, prevMatches: prevMatches, chainMatches: chainMatches });
    expectedPrev = e.chainHash;
  }
  return { ok: Array.isArray(entries) && checks.every(function(c){ return c.ok; }), checks: checks };
}

/* ---------- the trust mesh: verify({ claim, sources }) gives VERIFIED or REFUSED, with the grounding trace ---------- */
// A claim is a sentence (or a few) that an agent says its sources support. VERIFIED needs all three:
//   1. every quotation in the claim ("...") is word for word in a cited source, at the offsets the trace gives;
//   2. every content word of the claim outside its quotations is in a cited source;
//   3. every number of the claim outside its quotations is in a cited source.
// A claim cites sources with [id] markers; a claim with no marker cites every source given. Anything short of all
// three is REFUSED, with one reason for each part that failed. No AI judges anything: it checks words, numbers and
// offsets, and it does not understand meaning.
var MESH_VERSION = 'citelock-mesh-v1';
var MESH_MAX_CLAIM = 2000;        // characters in one claim: check a long text one sentence at a time
var MESH_MAX_SOURCES = 50;
var MESH_MAX_TEXT = 1000000;      // characters across all the sources of one call
var MESH_NEAR_MAX = 300;          // a longer quotation is not searched for its closest passage (that search is slow)
var MESH_ID = /^[A-Za-z0-9_.:-]+$/;
var MESH_NUMBER = /\d+(?:[.,]\d+)*/g;
var MESH_WORD = /[\p{L}\p{N}]+(?:'[\p{L}\p{N}]+)*/gu;
var MESH_QUOTE = /"[^"]*"/g;
var MESH_CITE = /\[([^\[\]]*)\]/g;
// Small words a claim may use without its source having them. Not in the list, because leaving them out changes what
// a claim says: negations (not, no, never, without), words of certainty (may, will, must) and of size or direction
// (over, under, up, down, more, less), and he, she and the other words for people.
var MESH_SKIP = new Set(('a an the and or but of to in on at by for from with into onto as than then so if ' +
  'is are was were be been being am has have had do does did it its they them their theirs this that these those ' +
  'there here which who whom whose what when where while also very just about ' +
  'according said says say states stated notes noted wrote writes cited cites').split(' '));

function meshSpaces(s){ return ' '.repeat(s.length); }

// A word folded so a simple plural or possessive matches its singular: "rates" and "rate", "companies" and
// "company", "board's" and "board". Nothing else is folded: "rose" and "rise" stay different words.
function meshFold(word){
  var w = word.toLowerCase();
  if (w.slice(-2) === "'s") w = w.slice(0, -2);
  if (w.length > 4 && w.slice(-3) === 'ies') return w.slice(0, -3) + 'y';
  if (w.length > 3 && w.slice(-1) === 's' && w.slice(-2) !== 'ss') return w.slice(0, -1);
  return w;
}

// A number as written, with thousands commas taken out: "1,200,000" and "1200000" are the same number. "3,5" and
// "12.0" stay as they are written, so 12.0 is not 12.
function meshNumberKey(tok){ return tok.replace(/,(?=\d{3}(?:\D|$))/g, ''); }

// The numbers and the words of a text, each with its offsets. Numbers are taken out first, so "Q3" gives the number 3
// and the word "Q", and "COVID-19" gives "COVID" and 19, the same way in a claim and in a source.
function meshTerms(text){
  var numbers = [], words = [];
  for (var m of text.matchAll(MESH_NUMBER)) numbers.push({ text: m[0], key: meshNumberKey(m[0]), start: m.index, end: m.index + m[0].length });
  for (var w of text.replace(MESH_NUMBER, meshSpaces).matchAll(MESH_WORD)) {
    words.push({ text: w[0], lower: w[0].toLowerCase(), key: meshFold(w[0]), start: w.index, end: w.index + w[0].length });
  }
  return { numbers: numbers, words: words };
}

// Where each character of the normalised source came from in the source exactly as given. Each character is
// normalised on its own and the pieces joined; when that does not rebuild the normalised text (a letter and its
// accent written as two characters, for example), there is no map and the trace gives no raw offsets for that source.
function meshMap(raw){
  var out = '', starts = [], ends = [], gap = false, i = 0;
  for (var ch of raw){
    var n = normalize(ch);
    if (n === '') gap = out !== '';
    else {
      if (gap){ out += ' '; starts.push(i); ends.push(i); gap = false; }
      for (var k = 0; k < n.length; k++){ starts.push(i); ends.push(i + ch.length); }
      out += n;
    }
    i += ch.length;
  }
  return out === normalize(raw) ? { starts: starts, ends: ends } : null;
}

// The raw offsets of a stretch [ns, ne) of the normalised source, or null. They are given only when the raw text
// there normalises back to exactly that stretch, so source.slice(start, end) always shows what was matched.
function meshRaw(src, ns, ne){
  if (src.map === undefined) src.map = meshMap(src.raw);
  if (src.map === null) return null;
  var a = src.map.starts[ns], b = src.map.ends[ne - 1];
  return normalize(src.raw.slice(a, b)) === src.norm.slice(ns, ne) ? [a, b] : null;
}

function meshRefuse(reason){
  return { verdict: 'REFUSED', algorithm: MESH_VERSION, reasons: [reason],
    trace: { claim: '', cited: [], checks: [{ kind: 'input', ok: false, reason: reason }], skipped: [], sources: [] } };
}

// Look a term up in each cited source, in the order the claim cites them; the first source that has it grounds it.
function meshFind(c, cited, lookup, reason){
  for (var i = 0; i < cited.length; i++){
    var hit = lookup(cited[i]);
    if (hit !== undefined){
      c.ok = true; c.source = cited[i].id; c.norm = [hit.start, hit.end]; c.raw = meshRaw(cited[i], hit.start, hit.end);
      return c;
    }
  }
  c.reason = reason;
  return c;
}

// The closest passage to a quotation that is not word for word in any cited source: the best NEAR_MATCH from
// verifyClaim above (the first source wins a tie), or null.
function meshNear(text, cited){
  if (text.length > MESH_NEAR_MAX) return null;
  var best = null;
  cited.forEach(function(src){
    var r = verifyClaim(text, src);
    if (r.verdict === 'NEAR_MATCH' && (best === null || r.similarity > best.similarity)) best = { source: src.id, similarity: r.similarity, excerpt: r.excerpt };
  });
  return best;
}

function meshQuote(text, at, cited){
  var c = { kind: 'quote', text: text, at: at, ok: false };
  if (text === '') { c.reason = 'the claim has an empty quotation'; return c; }
  meshFind(c, cited, function(src){
    var i = findWhole(src.norm, text);
    return i === -1 ? undefined : { start: i, end: i + text.length };
  }, 'the quotation "' + text + '" is not word for word in any cited source');
  if (c.ok) return c;
  var near = meshNear(text, cited);
  if (near !== null){
    c.closest = near;
    c.reason += '; the closest passage, in source ' + near.source + ', is ' + (near.similarity * 100).toFixed(1) + '% alike: ' + near.excerpt;
  }
  return c;
}

function meshVerify(input){
  if (input === null || typeof input !== 'object') return meshRefuse('the input must be an object: { claim, sources }');
  var list = input.sources;
  if (typeof input.claim !== 'string') return meshRefuse('the claim must be text');
  if (input.claim.length > MESH_MAX_CLAIM) return meshRefuse('the claim is longer than ' + MESH_MAX_CLAIM + ' characters: check it one sentence at a time');
  if (!Array.isArray(list) || list.length === 0 || list.length > MESH_MAX_SOURCES) return meshRefuse('sources must be a list of 1 to ' + MESH_MAX_SOURCES + ' sources');
  var sources = [], total = 0;
  for (var i = 0; i < list.length; i++){
    var s = list[i], obj = s !== null && typeof s === 'object';
    var text = obj ? s.text : s;
    if (typeof text !== 'string') return meshRefuse('source ' + (i + 1) + ' has no text');
    var id = obj && s.id !== undefined ? String(s.id) : String(i + 1);
    if (!MESH_ID.test(id)) return meshRefuse('source ' + (i + 1) + ': an id may only use letters, digits and . _ : -');
    if (sources.some(function(x){ return x.id === id; })) return meshRefuse('two sources have the id ' + id);
    total += text.length;
    if (total > MESH_MAX_TEXT) return meshRefuse('the sources add up to more than ' + MESH_MAX_TEXT + ' characters');
    var norm = normalize(text), t = meshTerms(norm), words = new Map();
    t.words.forEach(function(w){ if (!words.has(w.key)) words.set(w.key, w); });
    sources.push({ id: id, raw: text, norm: norm, numbers: t.numbers, words: words, map: undefined });
  }

  var claim = normalize(input.claim), checks = [], cited = [], marked = false;
  // citations first: [s1] or [s1, s2] outside the quotations. A bracket that is not a list of ids ("[the board]") is text.
  var rest = claim.replace(MESH_QUOTE, meshSpaces).replace(MESH_CITE, function(whole, inner, at){
    var ids = inner.split(',').map(function(x){ return x.trim(); });
    if (!ids.every(function(x){ return MESH_ID.test(x); })) return whole;
    marked = true;
    ids.forEach(function(x){
      var src = sources.find(function(y){ return y.id === x; });
      var c = { kind: 'cite', text: x, at: [at, at + whole.length], ok: src !== undefined };
      if (src === undefined) c.reason = 'the claim cites [' + x + '], which is not one of the sources given';
      else if (cited.indexOf(src) === -1) cited.push(src);
      checks.push(c);
    });
    return meshSpaces(whole);
  });
  if (!marked) cited = sources;

  // 1. each quotation, word for word
  for (var q of claim.matchAll(MESH_QUOTE)) checks.push(meshQuote(normalize(q[0].slice(1, -1)), [q.index, q.index + q[0].length], cited));
  var stray = rest.indexOf('"');
  if (stray !== -1) checks.push({ kind: 'quote', text: '"', at: [stray, stray + 1], ok: false, reason: 'the claim opens a quotation and never closes it' });

  // 2 and 3. each number and each content word outside the quotations, once each
  var terms = meshTerms(rest), seenNumbers = new Set(), seenWords = new Set(), skipped = [];
  terms.numbers.forEach(function(n){
    if (seenNumbers.has(n.key)) return;
    seenNumbers.add(n.key);
    checks.push(meshFind({ kind: 'number', text: n.text, at: [n.start, n.end], ok: false }, cited,
      function(src){ return src.numbers.find(function(x){ return x.key === n.key; }); },
      'the number ' + n.text + ' is not in any cited source'));
  });
  terms.words.forEach(function(w){
    if (w.text.length < 2 || MESH_SKIP.has(w.lower)){
      if (skipped.indexOf(w.lower) === -1) skipped.push(w.lower);
      return;
    }
    if (seenWords.has(w.key)) return;
    seenWords.add(w.key);
    checks.push(meshFind({ kind: 'word', text: w.text, at: [w.start, w.end], ok: false }, cited,
      function(src){ return src.words.get(w.key); },
      'the word "' + w.text + '" is not in any cited source'));
  });

  var reasons = [];
  checks.forEach(function(c){ if (!c.ok) reasons.push(c.reason); });
  if (!checks.some(function(c){ return c.kind !== 'cite'; })) reasons.push('nothing to check: the claim has no quotation, no content word and no number');
  return {
    verdict: reasons.length === 0 ? 'VERIFIED' : 'REFUSED',
    algorithm: MESH_VERSION,
    reasons: reasons,
    trace: {
      claim: claim,
      cited: cited.map(function(x){ return x.id; }),
      checks: checks,
      skipped: skipped,
      sources: sources.map(function(x){ return { id: x.id, length: x.raw.length }; })
    }
  };
}

// The one entry point. It never throws: input it cannot read is REFUSED with the reason.
function verify(input){
  try { return meshVerify(input); }
  catch (e) { return meshRefuse('the input could not be read'); }
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — CiteLock on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-citelock.mjs, the single file the Agensi skill runs. It reads one JSON input (a file, or `-`
// for stdin), verifies every claimed quote against its source and prints a JSON report.
// Exit 0 = every quote VERIFIED · 1 = at least one is not · 2 = the input could not be used.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-citelock.mjs <input.json | ->
input:  {"sources": [{"label": "…", "text": "…"} or {"label": "…", "file": "path/to/source.txt"}],
         "claims":  [{"source": "<a source label>", "quote": "…", "locator": "optional, e.g. p. 4"}]}
output: a JSON report on stdout. exit 0 = every quote VERIFIED, 1 = at least one is not, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path, what) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${what}: ${e.code || e.message}`); }
}

async function citelock(input) {
  if (!input || typeof input !== 'object' || !Array.isArray(input.sources) || !Array.isArray(input.claims)) {
    fail('input needs a "sources" array and a "claims" array');
  }
  const sources = [];
  for (const [i, s] of input.sources.entries()) {
    const label = typeof s?.label === 'string' ? s.label.trim() : '';
    if (!label) fail(`sources[${i}] needs a "label"`);
    if (sources.some((x) => x.label === label)) fail(`sources[${i}]: the label "${label}" is used twice`);
    const text = typeof s.text === 'string' ? s.text
      : typeof s.file === 'string' ? readText(s.file, `sources[${i}].file ${s.file}`)
      : fail(`sources[${i}] needs "text" or "file"`);
    if (!normalize(text)) fail(`sources[${i}] ("${label}") is empty`);
    sources.push(await makeSource(label, text));
  }
  const claims = input.claims.map((c, i) => {
    if (typeof c?.quote !== 'string' || !c.quote.trim()) fail(`claims[${i}] needs a non-empty "quote"`);
    if (typeof c.source !== 'string') fail(`claims[${i}] needs "source": the label of the source it quotes`);
    return { sourceLabel: c.source.trim(), quoteRaw: c.quote.trim(), locator: typeof c.locator === 'string' ? c.locator.trim() : '' };
  });
  if (!claims.length) fail('there are no claims to check');

  const results = verifyAll(sources, claims);
  const canonical = canonicalJSON(receiptPayload(sources, claims, results));
  const summary = summarizeVerdicts(results);
  const allVerified = results.every((r) => r.verdict === 'VERIFIED');
  return {
    exitCode: allVerified ? 0 : 1,
    report: {
      tool: 'kar-citelock',
      algorithm: ALGO_VERSION,
      verdict: allVerified ? 'ALL_VERIFIED' : 'NOT_ALL_VERIFIED',
      summary,
      results: claims.map((c, i) => ({
        source: c.sourceLabel,
        locator: c.locator,
        quote: normalize(c.quoteRaw),
        verdict: results[i].verdict,
        similarity: Number(results[i].similarity.toFixed(4)),
        excerpt: results[i].excerpt,
      })),
      sources: sources.map((s) => ({ label: s.label, sha256: s.hash, length: s.length })),
      receipt: { sha256: await sha256Hex(canonical), canonical },
    },
  };
}

async function main(args) {
  if (args.length !== 1 || args[0] === '-h' || args[0] === '--help') { process.stderr.write(USAGE + '\n'); return 2; }
  const raw = readText(args[0], args[0] === '-' ? 'stdin' : args[0]);
  let input;
  try { input = JSON.parse(raw); } catch (e) { fail(`the input is not valid JSON (${e.message})`); }
  const { exitCode, report } = await citelock(input);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  return exitCode;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-citelock: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
